const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

const net = require('net_helper')
const ws_client = require('ws_client')

const search_bar = require('search_bar')
const square_button = require('square_button')
const add_contact_popup = require('add_contact_popup')
const contact_row = require('contact_row')

module.exports = contacts_list

async function contacts_list(opts = {}) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject,
    data: ondata,
  }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="contact-list-container">
      <div class="contact-list-header">Contacts</div>

      <div class="top-bar">
        <div class="search-bar"></div>
        <div class="square-button" id="square-button"></div>
        <div class="add-contact-popup hidden"></div>
      </div>

      <div class="contacts-wrapper"></div>
    </div>
    <style></style>
  `

  // Query Selectors
  const style = shadow.querySelector('style')
  const contact_list_container = shadow.querySelector('.contact-list-container')
  const search_bar_el = shadow.querySelector('.search-bar')
  const square_button_el = shadow.querySelector('.square-button')
  const square_button_id = shadow.querySelector('#square-button')
  const add_contact_el = shadow.querySelector('.add-contact-popup')
  const contacts_wrapper = shadow.querySelector('.contacts-wrapper')

  // popup mounting
  let add_contact_mounted = false

  // -------------------- net_helper + ws_client setup --------------------
  const { io, _ } = net(id)
  io.on.backend = io_backend()
  io.on.home_contents = function (m) {
    if (m.type === 'update') renderContacts(m.data)
  }
  io.accept(make_ws_backend_invite('backend'))
  el.invite = io.invite('home_contents', { contacts_list: id })

  // subs
  const subs = await sdb.watch(onbatch)

  // Live contact data cache - used by search to filter
  let allContacts = []
  let contactElements = [] // { el, name }

  // search bar component
  const search = await search_bar(subs[0], msg => {
    if (msg.type === 'search') {
      const value = msg.value.toLowerCase()
      contactElements.forEach(({ el, name }) => {
        const isVisible = name.toLowerCase().includes(value)
        el.style.display = isVisible ? '' : 'none'
      })
    }
  })
  search_bar_el.replaceWith(search)

  // square button component
  const button = await square_button(subs[1])
  square_button_el.append(button)

  // add contact popup component
  square_button_id.addEventListener('click', async () => {
    const is_visible = !add_contact_el.classList.contains('hidden')

    if (is_visible) {
      add_contact_el.classList.add('hidden')
    } else {
      add_contact_el.classList.remove('hidden')

      if (!add_contact_mounted) {
        const add_contact_popup_comp = await add_contact_popup(subs[2], {
          onClose: () => {
            add_contact_el.classList.add('hidden')
          },
          // onSubmit fires when the user clicks Save Contact in add_new_contact
          onSubmit: function (data) {
            const name = (data.name || '').trim()
            const address = (data.address || '').trim()
            const note = (data.note || '').trim()
            if (!name || !address) return

            // Detect address type from address format
            let type = 'LN'
            if (/^[0-9a-fA-F]{66}$/.test(address)) type = 'NodeID'
            else if (/^(bc1|bcrt1|tb1|1|3)/.test(address)) type = 'BTC'

            // Show toast immediately — don't wait for backend response
            add_contact_el.classList.add('hidden')
            showToast('Contact added!', 'success')

            const head = _.backend('contact_add', { cause: [] }, { name, address, type, note })
            wait[head[2]] = function () {
              // Refresh list once backend confirms
              refreshContacts()
            }
          }
        })
        add_contact_el.append(add_contact_popup_comp)
        add_contact_mounted = true
      }
    }
  })

  // Render fallback contacts from subs (STATE) on first load
  for (let i = 3; i < subs.length; i++) {
    const contactData = subs[i]
    const contactEl = await contact_row(contactData, msg => {
      if (msg.type === 'contact-name') {
        console.log('[ContactList] contact name received:', msg.name)
      }
    })
    contacts_wrapper.append(contactEl)
    console.log('[ContactRow appended from subs] contactEl:', contactEl)
  }

  return el

  // -------------------- Live render from backend --------------------
  async function renderContacts(contactsArray) {
    if (!Array.isArray(contactsArray)) return

    // Clear existing live rows
    contacts_wrapper.innerHTML = ''
    contactElements = []

    if (contactsArray.length === 0) {
      contacts_wrapper.innerHTML = '<div style="text-align:center; color:gray; padding:20px; font-size:14px;">No contacts yet</div>'
      return
    }

    for (const contact of contactsArray) {
      // Create a live row element directly
      const rowEl = document.createElement('div')
      const rowShadow = rowEl.attachShadow({ mode: 'open' })

      const avatar = contact.avatar || `https://api.dicebear.com/7.x/identicon/svg?seed=${encodeURIComponent(contact.name || contact.id || 'contact')}`
      const name = contact.name || contact.id || 'Unknown'
      const message = contact.last_message || contact.message || ''
      const time = contact.time || contact.last_time || ''
      const unread = contact.unread || 0
      const online = contact.online || false
      const type = contact.type || ''
      const p2pEnabled = contact.p2p_enabled === true

      // Type badge colour
      const typeBadgeColor = type === 'BTC' ? '#f59e0b' : type === 'NodeID' ? '#6b7280' : '#3b82f6'
      const typeBadgeText = type || 'LN'

      rowShadow.innerHTML = `
        <div class="contact-row">
          <div class="contact-left">
            <div class="contact-avatar">
              <img src="${avatar}" alt="${name}" />
              ${online ? '<div class="online-dot"></div>' : ''}
            </div>
            <div class="contact-info">
              <div class="contact-name-row">
                <div class="contact-name">${name}</div>
                <div class="type-badge" style="background:${typeBadgeColor}">${typeBadgeText}</div>
                <div class="chat-status-badge ${p2pEnabled ? 'enabled' : 'disabled'}">${p2pEnabled ? 'Chat Enabled' : 'Chat Disabled'}</div>
              </div>
              <div class="contact-message ${unread > 0 ? 'unread-message' : ''}">
                ${message}
              </div>
            </div>
          </div>
          <div class="contact-right">
            <div class="contact-time">${time}</div>
            ${unread > 0 ? `<div class="unread-badge">${unread}</div>` : ''}
            <button class="delete-btn" title="Remove contact">Del</button>
          </div>
        </div>
        <style>
          .contact-row {
            display: flex;
            flex-direction: row;
            align-items: center;
            justify-content: space-between;
            padding: 10px 8px;
            border-radius: 10px;
            cursor: pointer;
            transition: background 0.2s;
            margin-bottom: 4px;
          }
          .contact-row:hover { background: #f5f5f5; }
          .contact-left { display: flex; align-items: center; gap: 10px; flex: 1; min-width: 0; }
          .contact-avatar { position: relative; flex-shrink: 0; }
          .contact-avatar img { width: 44px; height: 44px; border-radius: 50%; object-fit: cover; }
          .online-dot { position: absolute; bottom: 1px; right: 1px; width: 10px; height: 10px; background: #4caf50; border: 2px solid white; border-radius: 50%; }
          .contact-info { display: flex; flex-direction: column; min-width: 0; }
          .contact-name-row { display: flex; align-items: center; gap: 6px; }
          .contact-name { font-weight: 600; font-size: 15px; color: #111; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
          .type-badge { font-size: 10px; font-weight: 700; color: white; border-radius: 4px; padding: 1px 5px; flex-shrink: 0; letter-spacing: 0.02em; }
          .chat-status-badge { font-size: 10px; font-weight: 700; border-radius: 4px; padding: 1px 5px; flex-shrink: 0; letter-spacing: 0.02em; }
          .chat-status-badge.disabled { color: #6b7280; background: #e5e7eb; }
          .chat-status-badge.enabled { color: #166534; background: #dcfce7; }
          .contact-message { font-size: 13px; color: #888; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
          .unread-message { color: #333; font-weight: 500; }
          .contact-right { display: flex; flex-direction: column; align-items: flex-end; gap: 4px; flex-shrink: 0; }
          .contact-time { font-size: 12px; color: #aaa; }
          .unread-badge { background: #f7931a; color: white; font-size: 11px; font-weight: 700; min-width: 18px; height: 18px; border-radius: 9px; display: flex; align-items: center; justify-content: center; padding: 0 4px; }
          .delete-btn { background: none; border: 1px solid #e0e0e0; color: #aaa; font-size: 11px; font-weight: 600; border-radius: 4px; padding: 2px 8px; cursor: pointer; transition: all 0.2s; margin-top: 2px; }
          .delete-btn:hover { background: #fff0f0; border-color: #f87171; color: #ef4444; }
        </style>
      `

      // Wire delete button, show toast immediately, refresh list after backend confirms
      const deleteBtn = rowShadow.querySelector('.delete-btn')
      deleteBtn.addEventListener('click', function (e) {
        e.stopPropagation()
        const contactId = contact.id
        if (!contactId) return
        const contactName = contact.name || 'Contact'

        // Show feedback immediately — optimistic UI
        showToast(contactName + ' removed', 'delete')

        const head = _.backend('contact_delete', { cause: [] }, { id: contactId })
        wait[head[2]] = function () {
          refreshContacts()
        }
      })

      rowShadow.querySelector('.contact-row').addEventListener('click', function () {
        el.dispatchEvent(new CustomEvent('open-contact-chat', {
          bubbles: true,
          composed: true,
          detail: { contact }
        }))
      })

      // Store for search filtering
      contactElements.push({ el: rowEl, name })
      contacts_wrapper.append(rowEl)
    }

    // Cache for search
    allContacts = contactsArray
  }

  // -------------------- Refresh contacts from backend --------------------
  function refreshContacts() {
    const head = _.backend('contact_list', { cause: [] }, {})
    wait[head[2]] = function (m) {
      const payload = m.data?.data
      if (!payload) return
      const contacts = Array.isArray(payload) ? payload : (payload.data || [])
      if (!Array.isArray(contacts)) return
      const formatted = contacts.map(function (c) {
        const seed = encodeURIComponent(c.address || c.name || c.id || 'contact')
        return {
          id: c.id || '',
          name: c.name || 'Unknown',
          avatar: `https://api.dicebear.com/7.x/identicon/svg?seed=${seed}`,
          message: c.note || (c.type ? c.type : ''),
          time: '',
          unread: 0,
          online: false,
          address: c.address || '',
          type: c.type || '',
          p2p_enabled: c.p2p_enabled === true
        }
      })
      renderContacts(formatted)
    }
  }


  function _getAppContainer() {
    try {
      const clHost = el.getRootNode().host            // contacts_list host el
      const menuShadow = clHost.getRootNode()             // menu's shadow root
      if (menuShadow && menuShadow.querySelector) {
        const cc = menuShadow.querySelector('.content-container')
        if (cc) return cc
      }
    } catch (e) { /* fall through */ }
    return document.body
  }

  function showToast(message, type) {
    const isSuccess = type === 'success'
    const icon = isSuccess ? '\u2713' : '\u2715'
    const bg = isSuccess
      ? 'linear-gradient(135deg, #22c55e 0%, #16a34a 100%)'
      : 'linear-gradient(135deg, #ef4444 0%, #dc2626 100%)'

    const container = _getAppContainer()

    const toast = document.createElement('div')
    // Use position:absolute so it stays inside the app frame container
    const positionType = container === document.body ? 'fixed' : 'absolute'
    toast.style.cssText = [
      `position:${positionType}`,
      'bottom:80px',          // above the tab bar
      'left:50%',
      'transform:translateX(-50%) translateY(16px)',
      'z-index:99999',
      'display:flex',
      'align-items:center',
      'gap:10px',
      'padding:12px 20px',
      `background:${bg}`,
      'box-shadow:0 6px 24px rgba(0,0,0,0.25)',
      'border-radius:12px',
      'font-size:13px',
      'font-weight:600',
      'color:white',
      'white-space:nowrap',
      'pointer-events:none',
      'font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Arial,sans-serif',
      'opacity:0',
      'transition:opacity 0.25s ease, transform 0.25s ease',
    ].join(';')

    // Circular icon badge
    const iconEl = document.createElement('span')
    iconEl.style.cssText = [
      'display:inline-flex',
      'align-items:center',
      'justify-content:center',
      'width:18px',
      'height:18px',
      'border-radius:50%',
      'background:rgba(255,255,255,0.28)',
      'font-size:11px',
      'font-weight:700',
      'flex-shrink:0',
    ].join(';')
    iconEl.textContent = icon

    const textEl = document.createElement('span')
    textEl.textContent = message

    toast.appendChild(iconEl)
    toast.appendChild(textEl)
    container.appendChild(toast)

    // Animate in
    requestAnimationFrame(() => {
      toast.style.opacity = '1'
      toast.style.transform = 'translateX(-50%) translateY(0)'
    })

    // Animate out then remove
    setTimeout(() => {
      toast.style.opacity = '0'
      toast.style.transform = 'translateX(-50%) translateY(16px)'
      setTimeout(() => toast.remove(), 280)
    }, 2800)
  }


  // -------------------- Backend response matching --------------------
  function io_backend() {
    return protocol
    function protocol(m) {
      const mid = m.head?.[2]
      if (mid === undefined) return
      const handler = wait[mid]
      if (!handler) return
      delete wait[mid]
      handler(m)
    }
  }

  const wait = {}

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(p => drive.get(p).then(f => f.raw)))
      const fn = on[type] || fail
      await fn(data, type)
    }
  }

  function inject(data) {
    style.textContent = data[0]
  }

  function fail(data, type) { throw new Error('invalid message', { cause: { data, type } }) }

  async function ondata(data) { }

  // ---- ws_client to net_helper bridge ----
  function make_ws_backend_invite(name) {
    return Object.assign(invite_fn, { ids: { [name]: ws_client.id } })
    function invite_fn(rx) {
      ws_client.bind(function (M) {
        try { rx(M) } catch (e) { console.error('[contacts_list] ws rx error:', e) }
      })
      const tx_fn = function (M) { ws_client.tx(M) }
      tx_fn.id = ws_client.id
      return tx_fn
    }
  }
}

function fallback_module() {

  return {
    api,
    _: {
      'search_bar': { $: '' },
      'square_button': { $: '' },
      'add_contact_popup': { $: '' },
      'contact_row': { $: '' },
      'net_helper': { $: '' },
      'ws_client': { $: '' },
    }
  }

  function api(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = []

    const search_bar = { mapping: { style: 'style', data: 'data', icons: 'icons' }, 0: {} }
    const square_button = { mapping: { style: 'style', data: 'data', icons: 'icons' }, 1: {} }
    const add_contact_popup = { mapping: { style: 'style', data: 'data', icons: 'icons' }, 2: {} }
    const contact_row = { mapping: { style: 'style', data: 'data', icons: 'icons' } }

    opts.value.forEach((contact, index) => {
      contact_row[index + 3] = contact
    })

    return {
      drive: {
        'style/': { 'style.css': { '$ref': 'contacts_list.css' } },
        'data/': { 'opts.json': { raw: opts || {} } }
      },
      _: { search_bar, square_button, add_contact_popup, contact_row }
    }
  }
}
